def grid_paths(rows, cols):
    ways = [[1] * cols for _ in range(rows)]  # top row, left column = 1
    for r in range(1, rows):
        for c in range(1, cols):
            ways[r][c] = ways[r - 1][c] + ways[r][c - 1]
    for row in ways:
        print(row)
    return ways[-1][-1]
